mapper.select:
SELECT request_fingerprint AS requestFingerprint, display_name AS displayName,
       tenant_status AS status, expires_at AS expiresAt,
       tenant_created_at AS createdAt, tenant_updated_at AS updatedAt
FROM tenant_detail_updates
WHERE tenant_id = #{key.tenantId} AND actor_identity_id = #{key.actorIdentityId}
  AND idempotency_key = #{key.idempotencyKey}

mapper.update:
UPDATE tenants SET display_name = #{tenant.displayName}, expires_at = #{tenant.expiresAt},
    updated_at = #{tenant.updatedAt}
WHERE id = #{tenant.id} AND tenant_status = #{tenant.status} AND tenant_status <> 'CLOSED'

UPDATE tenant_detail_updates SET display_name = #{snapshot.tenant.displayName},
    tenant_status = #{snapshot.tenant.status}, expires_at = #{snapshot.tenant.expiresAt},
    tenant_created_at = #{snapshot.tenant.createdAt}, tenant_updated_at = #{snapshot.tenant.updatedAt},
    completed_at = #{snapshot.completedAt}
WHERE tenant_id = #{snapshot.key.tenantId}
  AND actor_identity_id = #{snapshot.key.actorIdentityId}
  AND idempotency_key = #{snapshot.key.idempotencyKey}
  AND completed_at IS NULL
